#include <limits>
#include <iostream>

void check_fp_support() {
    using L = std::numeric_limits<float>;

    if (L::has_infinity) {
        std::cout << "Infinity: " << L::infinity() << "\n";
    }

    if (L::has_quiet_NaN) {
        std::cout << "Quiet NaN: " << L::quiet_NaN() << "\n";
    }

    // Using has_denorm as a boolean (since denorm_absent is 0)
    if (L::has_denorm) {
        std::cout << "Denormals are present or indeterminate.\n";
    }
}

int main() {
    check_fp_support();
}
